package io.reactivex.rxjava3.internal.operators.observable;

import java.util.concurrent.*;
import io.reactivex.rxjava3.core.*;
import io.reactivex.rxjava3.disposables.*;
import io.reactivex.rxjava3.observers.*;

public class Repro {
    public static void main(String[] args) throws Exception {
        // Blocks inside subscribeActual so the parent can be disposed
        // BEFORE the inner's onSubscribe is delivered:
        // inner.cancel() sets the disposable field to DISPOSED,
        // so setOnce fails, queue stays null, and the synchronous
        // onNext afterwards hits queue.offer on a null queue.
        final CountDownLatch subscribed = new CountDownLatch(1);
        final CountDownLatch release = new CountDownLatch(1);

        Observable<Integer> inner = new Observable<Integer>() {
            @Override
            protected void subscribeActual(Observer<? super Integer> observer) {
                subscribed.countDown();
                try {
                    release.await();
                } catch (InterruptedException e) { }
                observer.onSubscribe(Disposables.empty());
                observer.onNext(1);
                observer.onComplete();
            }
        };

        final StringBuilder sb = new StringBuilder();
        Disposable d = Observable.just(1)
            .switchMap(v -> inner)
            .subscribe(new DisposableObserver<Integer>() {
                @Override public void onNext(Integer t) { sb.append(t); }
                @Override public void onError(Throwable e) { System.out.println("ERROR: " + e); }
                @Override public void onComplete() { }
            });

        subscribed.await();
        d.dispose();
        release.countDown();
        Thread.sleep(200);
        System.out.println("done, received: [" + sb + "]");
    }
}

